function Result({value}:{value:number|null}){return <div className="result-box" aria-live="polite"><span>Result</span><strong>{value===null||!Number.isFinite(value)?"Enter valid inputs":value.toLocaleString(undefined,{maximumFractionDigits:12})}</strong></div>}
function LaunchTool({slug}:{slug:string}){const spec=getLaunchSpec(slug)!;const definition=useMemo(()=>launchDefinition(spec),[spec]);const[values,setValues]=useState<Record<string,string>>(()=>Object.fromEntries(spec.fields.map(x=>[x.key,String(x.defaultValue)])));const input=useMemo(()=>Object.fromEntries(spec.fields.map(x=>[x.key,Number(values[x.key])])),[spec,values]);const result=useMemo(()=>{try{const n=runCalculator(definition,input).output.result;return Number.isFinite(n)?n:null}catch{return null}},[definition,input]);return <div className="calculator-ui"><div className="field-grid">{spec.fields.map(field=><NumberField key={field.key} label={field.label} min={field.min} value={values[field.key]??""} onChange={value=>setValues(current=>({...current,[field.key]:value}))}/>)}</div><Result value={result}/><CalculatorAccountActions calculatorSlug={slug} calculatorVersion={1} input={input} output={result===null?null:{result}}/>{result!==null&&<AiResultExplanation calculatorName={spec.title} formula={spec.formula} assumptions={["The displayed deterministic formula is the source of the numeric result."]} values={input} result={{result}}/>}</div>}
export function CalculatorInteractive({slug}:{slug:string}){if(slug===loanAnalysisCalculator.slug)return <LoanPaymentReferenceTool calculatorSlug={loanAnalysisCalculator.slug}/>;if(slug===loanPaymentCalculator.slug)return <LoanPaymentReferenceTool calculatorSlug={loanPaymentCalculator.slug}/>;if(slug==="mortgage-payment")return <MortgageReferenceTool/>;if(slug===bmiCalculator.slug)return <BmiReferenceTool/>;if(slug===breakEvenCalculator.slug)return <BreakEvenReferenceTool/>;if(slug===percentageCalculator.slug)return <PercentageTool/>;if(slug===unitConversionCalculator.slug)return <UnitTool/>;if(slug===simpleInterestCalculator.slug)return <SimpleInterestTool/>;if(slug===savingsGoalCalculator.slug)return <SavingsGoalTool/>;if(slug===emergencyFundCalculator.slug)return <EmergencyFundTool/>;if(slug===roiCalculator.slug)return <RoiTool/>;if(slug===inflationCalculator.slug)return <InflationTool/>;if(slug===rateConversionCalculator.slug)return <RateConversionTool/>;if(slug===loanAnalysisCalculator.slug)return <LoanAnalysisTool/>;if(slug===netWorthCalculator.slug)return <NetWorthTool/>;if(slug===termDepositCalculator.slug)return <TermDepositTool/>;if(slug===recurringDepositCalculator.slug)return <RecurringDepositTool/>;if(slug===sipCalculator.slug)return <SipTool/>;if(slug===stepUpSipCalculator.slug)return <StepUpSipTool/>;if(slug===swpCalculator.slug)return <SwpTool/>;if(slug===creditCardPayoffCalculator.slug)return <CreditCardTool/>;if(slug===loanAffordabilityCalculator.slug)return <AffordabilityTool/>;if(slug===loanRefinanceCalculator.slug)return <RefinanceTool/>;if(slug===loanPrepaymentCalculator.slug)return <PrepaymentTool/>;if(slug===loanComparisonCalculator.slug)return <LoanComparisonTool/>;if(slug===investmentMathCalculator.slug)return <InvestmentGrowthTool/>;if(slug===debtPayoffCalculator.slug)return <DebtPayoffTool/>;if(slug===compoundInterestCalculator.slug)return <CompoundInterestTool/>;if(getLaunchSpec(slug))return <LaunchTool slug={slug}/>;return <p className="muted">This calculator does not yet have a public interface.</p>}
